def is_balanced(text):
    """
    Check if the text contains properly balanced parentheses ((), [], {})

    Args:
        text (str): The input string to check

    Returns:
        bool: True if brackets are balanced, False otherwise
    """
    stack = []

    for char in text:
        if char == '(':
            stack.append('(')
        elif char == ')':
            if not stack or stack.pop() != '(':
                return False
        elif char == '[':
            stack.append('[')
        elif char == ']':
            if not stack or stack.pop() != '[':
                return False
        elif char == '{':
            stack.append('{')
        elif char == '}':
            if not stack or stack.pop() != '{':
                return False

    return len(stack) == 0


# Example usage:
if __name__ == "__main__":
    print(is_balanced("()[]{}"))      # True
    print(is_balanced("(())[()]"))     # True
    print(is_balanced("({}){{}}"))     # False
```
